UPDATE Diplomacy_Responses SET Response='TXT_KEY_LIBRARY_EXILE_INTRO',Bias=1 WHERE LeaderType='LEADER_TRENT_LIBRARY_EXILE' AND ResponseType='RESPONSE_FIRST_GREETING';
UPDATE Diplomacy_Responses SET Response='TXT_KEY_LIBRARY_EXILE_NEUTRAL',Bias=1 WHERE LeaderType='LEADER_TRENT_LIBRARY_EXILE' AND ResponseType='RESPONSE_GREETING_NEUTRAL_HELLO';
