UPDATE Diplomacy_Responses SET Response='TXT_KEY_LIBRARY_EXILE_HOSTILE',Bias=4 WHERE LeaderType='LEADER_TRENT_LIBRARY_EXILE' AND ResponseType='RESPONSE_GREETING_HOSTILE_HELLO';
INSERT INTO Diplomacy_Responses (LeaderType,ResponseType,Response,Bias) VALUES
('LEADER_TRENT_LIBRARY_EXILE','RESPONSE_GREETING_HOSTILE_HELLO','TXT_KEY_LIBRARY_EXILE_RARE_HOSTILE',1),
('LEADER_TRENT_LIBRARY_EXILE','RESPONSE_WORK_WITH_US_YES','TXT_KEY_LIBRARY_EXILE_DOF',1),
('LEADER_TRENT_LIBRARY_EXILE','RESPONSE_RESPONSE_TO_BEING_DENOUNCED','TXT_KEY_LIBRARY_EXILE_DENOUNCED',1);
UPDATE Diplomacy_Responses SET Response='TXT_KEY_LIBRARY_EXILE_DOW',Bias=1 WHERE LeaderType='LEADER_TRENT_LIBRARY_EXILE' AND ResponseType='RESPONSE_DOW_GENERIC';
UPDATE Diplomacy_Responses SET Response='TXT_KEY_LIBRARY_EXILE_ATTACKED',Bias=1 WHERE LeaderType='LEADER_TRENT_LIBRARY_EXILE' AND ResponseType='RESPONSE_ATTACKED_HOSTILE';
UPDATE Diplomacy_Responses SET Response='TXT_KEY_LIBRARY_EXILE_DEFEATED',Bias=1 WHERE LeaderType='LEADER_TRENT_LIBRARY_EXILE' AND ResponseType='RESPONSE_DEFEATED';
UPDATE Diplomacy_Responses SET Response='TXT_KEY_LIBRARY_EXILE_ACCEPT',Bias=1 WHERE LeaderType='LEADER_TRENT_LIBRARY_EXILE' AND ResponseType IN ('RESPONSE_TRADE_ACCEPT_ACCEPTABLE','RESPONSE_TRADE_ACCEPT_GENEROUS');
UPDATE Diplomacy_Responses SET Response='TXT_KEY_LIBRARY_EXILE_REJECT',Bias=1 WHERE LeaderType='LEADER_TRENT_LIBRARY_EXILE' AND ResponseType IN ('RESPONSE_TRADE_REJECT_INSULTING','RESPONSE_TRADE_REJECT_UNACCEPTABLE');
